	class BossFieldSoulShopItem extends BaseItemRenderer {
	    constructor(parent) {
	        super();
	        this.WIDTH = 602;
	        this.HEIGT = 258;
	        this.base_file = "bossField";
	        this.layout_file = "BossFieldSoulShopItem";
	        this.load_callback = () => {
	            this.LoadSuccess();
	        };
	        this.Load();
	    }
	    LoadSuccess() {
	    }
	    dataChanged() {
	        if (super.dataChanged()) {
	            let view_class = window["BossFieldSoulShopSubItem"];
	            if (!view_class)
	                return;
	            let data = this.data;
	            let length = data.length;
	            if (!this.item_list) {
	                this.item_list = [];
	            }
	            let i = 0;
	            do {
	                let item = this.item_list[i];
	                if (!item) {
	                    item = new view_class(this._hbox_con);
	                    item.Load();
	                    table.insert(this.item_list, item);
	                }
	                if (i < length) {
	                    item.SetData(data[i]);
	                    item.SetVisible(true);
	                }
	                else {
	                    item.SetVisible(false);
	                }
	                i = i + 1;
	            } while ((i < 3));
	        }
	    }
	    DeleteMe() {
	        if (this.item_list && this.item_list.length > 0) {
	            for (let _tmpi in this.item_list) {
	                var obj = this.item_list[_tmpi];
	                obj.DeleteMe();
	            }
	            this.item_list = null;
	        }
	        super.DeleteMe();
	    }
	    GetComponents() {
	        [
	            this._img_line,
	            this._hbox_con,
	        ]
	            = this.GetChildrenByNames([
	                "_img_line",
	                "_hbox_con",
	            ]);
	    }
	}
