	        this.key_id = data.key_id;
	        this.goods_id = data.goods_id;
	        this.num = data.num;
	        this.price = data.price;
	        this.quota_num = data.quota_num;
	        this.sold_out = data.sold_out;
	        this.can_buy = this.sold_out < this.quota_num;
	        if (this.is_loaded) {
	            this.UpdataView();
	        }
	        else {
	            this.need_refresh_data = true;
	        }
