	                        cfg["_btn_left"] = { visible: false };
	                        cfg["_lb_right"] = { text: "确定" };
	                        cfg["_btn_right"] = { centerX: 0 };
	                        cfg["_gp_reward_con"] = { visible: true };
	                        cfg["_gp_tip_1"] = { visible: true };
