	                let color_top = (enough_goods_top && (Enum_ColorUtil_Dark.GREEN) || (Enum_ColorUtil_Dark.RED));
	                let str = HtmlColorTxt(own_top, color_top);
	                let result = Util.StrToHTML(str + "/" + cost_num_top_);
