	class Kf1vnMatchSuccessView extends BaseView1 {
	    constructor() {
	        super();
	        this.base_file = "kf1vn";
	        this.layout_file = "Kf1vnMatchSuccessView";
	        this.layer_value = Enum_UILayer.Activity;
	        this.back_login_close = true;
	        this.destroy_imm = true;
	        this.use_background = true;
	        this.background_alpha = 0;
	        let model = Kf1vnModel.GetInstance();
	        let auto_fight_mgr = AutoFightManager.GetInstance();
	        let layer_mgr = LayerManager.GetInstance();
	        let local_Math = Math;
	        let data_ = null;
	        let list_time = [];
	        let center_x_ = null;
	        let center_y_ = null;
	        this.anim_list = [];
	        let voice;
	        this.load_callback = () => {
	            if (!list_time)
	                list_time = [];
	            this.LoadSuccess();
	            this.InitEvent();
	        };
	        this.open_callback = () => {
	            this.OpenCallback();
	        };
	        this.ClearTime = () => {
	            for (let i = 0; i < list_time.length; i++) {
	                clearTimeout(list_time[i]);
	            }
	            list_time.length = 0;
	        };
	        this.destroy_callback = () => {
	            if (voice) {
	                SoundManager.GetInstance().StopSoundEffect(voice);
	                voice = null;
	            }
	            this.ClearTime();
	            if (this.head11) {
	                this.head11.DeleteMe();
	                this.head11 = null;
	            }
	            if (this.head22) {
	                this.head22.DeleteMe();
	                this.head22 = null;
	            }
	            if (this.anim_list && this.anim_list.length > 0) {
	                for (let i = 0; i < this.anim_list.length; i++) {
	                    var v = this.anim_list[i];
	                    SYTweenLite.Stop(v);
	                }
	                this.anim_list = [];
	            }
	            if (this.load_complete_id) {
	                GlobalEventSystem.UnBind(this.load_complete_id);
	                this.load_complete_id = null;
	            }
	        };
	        this.LoadSuccess = () => {
	            ResManager.GetInstance().SetOutsideImageSprite(this, this.left_img, GameResPath.GetIcon("kf1vn", "uikf1vn_023"));
	            ResManager.GetInstance().SetOutsideImageSprite(this, this.right_img, GameResPath.GetIcon("kf1vn", "uikf1vn_024"));
	            center_x_ = this.center_conta.x;
	            center_y_ = this.center_conta.y;
	            this.head11 = new CustomHeadItem(this.head1);
	            this.head11.CloseClick();
	            this.head11.Load();
	            this.head22 = new CustomHeadItem(this.head2);
	            this.head22.CloseClick();
	            this.head22.Load();
	            voice = CommonManager.GetInstance().PlayFightingVoice(3);
	        };
	        this.InitEvent = () => {
	        };
	        this.Local_Open = (parms) => {
	            data_ = parms && parms[0] || null;
	            if (!data_) {
	                let sInfo = model.stage_info;
	                if (sInfo) {
	                    if (sInfo.stage == 3) {
	                        data_ = model.ticket_fighting_info;
	                    }
	                    else if (sInfo.stage == 5) {
	                        data_ = model.leader_fighting_info;
	                    }
	                }
	            }
	            super.Open();
	        };
	        this.OpenCallback = () => {
	            if (data_) {
	                let leftTime = data_.loading_time - TimeUtil.getServerTime();
	                if (leftTime >= 4) {
	                    leftTime = 4;
	                }
	                if (leftTime < 1) {
	                    this.Close();
	                    setTimeout(() => {
	                        auto_fight_mgr.SetAutoFight(true);
	                    }, leftTime * 1000);
	                    return;
	                }
	                if (data_.battle_list[0]) {
	                    let vo = data_.battle_list[0];
	                    this.role_name1.text = vo.name;
	                    let head_data = { role_id: vo.player_id, picture: vo.picture, picture_ver: vo.picture_ver };
	                    this.head11.SetRoleVoData(head_data, null, null, vo.lv);
	                    this.fight1.text = `战力：${vo.combat_power}`;
	                    this.server1.text = `【S${vo.server_num}】`;
	                }
	                if (data_.battle_list[1]) {
	                    let vo = data_.battle_list[1];
	                    this.role_name2.text = vo.name;
	                    let head_data2 = { role_id: vo.player_id, picture: vo.picture, picture_ver: vo.picture_ver };
	                    this.head22.SetRoleVoData(head_data2, null, null, vo.lv);
	                    this.fight2.text = `战力：${vo.combat_power}`;
	                    this.server2.text = `【S${vo.server_num}】`;
	                }
	                if (leftTime > 2) {
	                    this.FadeIn();
	                }
	                else if (leftTime > 1) {
	                    SetAnchoredPositionX(this.left_conta, 0);
	                    SetAnchoredPositionX(this.right_conta, 0);
	                    this.center_conta.alpha = 1;
	                    let id = setTimeout(() => {
	                        if (!this.use_delete_method) {
	                            this.FadeOut();
	                        }
	                    }, (leftTime - 1) * 1000);
	                    table.insert(list_time, id);
	                }
	                else {
	                    this.FadeOut();
	                }
	            }
	        };
	        this.FadeIn = () => {
	            this.ClearTime();
	            let flyWidth = layer_mgr.stageWidth / 2;
	            SetAnchoredPositionX(this.left_conta, -flyWidth);
	            SetAnchoredPositionX(this.right_conta, flyWidth);
	            this.vs.visible = false;
	            SetLocalScale(this.center_conta, 5, 5, 5);
	            SetAnchoredPositionY(this.center_conta, this.center_conta.y + 200);
	            SetAnchoredPositionX(this.center_conta, this.center_conta.x - 50);
	            SYTweenLite.Stop(this.anim_list["center1"]);
	            SYTweenLite.Stop(this.anim_list["center2"]);
	            this.anim_list["center1"] = SYTweenLite.to(this, this.center_conta, SYTweenLite.UiAnimationType.ANCHORED_POS, new Vector2(center_x_, center_y_), 0.3, null, SYTweenFunc.EASE_IN, false);
	            this.anim_list["center2"] = SYTweenLite.to(this, this.center_conta, SYTweenLite.UiAnimationType.SCALE, { x: 1, y: 1, z: 1 }, 0.3, null, SYTweenFunc.EASE_IN, false);
	            let id = setTimeout(() => {
	                if (this.use_delete_method) {
	                    return;
	                }
	                SYTweenLite.Stop(this.anim_list["left"]);
	                this.anim_list["left"] = SYTweenLite.to(this, this.left_conta, SYTweenLite.UiAnimationType.ANCHORED_POSX, 0, 0.25, () => {
	                    let delayTime = data_.loading_time - TimeUtil.getServerTime();
	                    if (delayTime >= 3) {
	                        delayTime = 3;
	                    }
	                    if (delayTime > 0) {
	                        let id2 = setTimeout(() => {
	                            if (!this.use_delete_method) {
	                                this.FadeOut();
	                            }
	                        }, delayTime * 1000);
	                        table.insert(list_time, id2);
	                    }
	                    else {
	                        this.FadeOut();
	                    }
	                }, SYTweenFunc.EASE_IN, false);
	                SYTweenLite.Stop(this.anim_list["right"]);
	                this.anim_list["right"] = SYTweenLite.to(this, this.right_conta, SYTweenLite.UiAnimationType.ANCHORED_POSX, 0, 0.25, null, SYTweenFunc.EASE_IN, false);
	                this.vs.visible = true;
	            }, 0.2 * 1000);
	            table.insert(list_time, id);
	        };
	        this.FadeOut = () => {
	            table.insert(this.anim_list, SYTweenLite.to(this, this.center_conta, SYTweenLite.UiAnimationType.ALPHA, 0, 0.7, null, SYTweenFunc.EASE_IN, false));
	            table.insert(this.anim_list, SYTweenLite.to(this, this.display_obj, SYTweenLite.UiAnimationType.ALPHA, 0, 0.7, null, SYTweenFunc.EASE_IN, false));
	            let len = 100;
	            let angle = 60 * local_Math.PI / 180;
	            let target_x = this.left_conta.x - len * local_Math.cos(angle);
	            let target_y = this.left_conta.y - len * local_Math.sin(angle);
	            let target_x2 = this.right_conta.x + len * local_Math.cos(angle);
	            let target_y2 = this.right_conta.y + len * local_Math.sin(angle);
	            SYTweenLite.Stop(this.anim_list["left"]);
	            table.insert(this.anim_list, SYTweenLite.to(this, this.left_conta, SYTweenLite.UiAnimationType.ANCHORED_POS, new Vector2(target_x, target_y), 0.7, null, SYTweenFunc.EASE_OUT, false));
	            table.insert(this.anim_list, SYTweenLite.to(this, this.left_conta, SYTweenLite.UiAnimationType.ALPHA, 0, 0.7, () => {
	                auto_fight_mgr.SetAutoFight(true);
	                this.Close();
	            }, SYTweenFunc.EASE_OUT, false));
	            SYTweenLite.Stop(this.anim_list["right"]);
	            table.insert(this.anim_list, SYTweenLite.to(this, this.right_conta, SYTweenLite.UiAnimationType.ANCHORED_POS, new Vector2(target_x2, target_y2), 0.7, null, SYTweenFunc.EASE_OUT, false));
	            table.insert(this.anim_list, SYTweenLite.to(this, this.right_conta, SYTweenLite.UiAnimationType.ALPHA, 0, 0.7, null, SYTweenFunc.EASE_OUT, false));
	        };
	    }
	    Open(...new_args) {
	        let parms = new_args;
	        this.Local_Open(parms);
	    }
	    DeleteMe() {
	        super.DeleteMe();
	    }
	    GetComponents() {
	        [
	            this._box_1,
	            this.left_conta,
	            this.left_img,
	            this.role_name1,
	            this.server1,
	            this.fight1,
	            this.head1,
	            this._box_2,
	            this.right_conta,
	            this.right_img,
	            this.fight2,
	            this.role_name2,
	            this.server2,
	            this.head2,
	            this._box_3,
	            this.center_conta,
	            this.icon,
	            this.vs,
	        ]
	            = this.GetChildrenByNames([
	                "_box_1",
	                "left_conta",
	                "left_img",
	                "role_name1",
	                "server1",
	                "fight1",
	                "head1",
	                "_box_2",
	                "right_conta",
	                "right_img",
	                "fight2",
	                "role_name2",
	                "server2",
	                "head2",
	                "_box_3",
	                "center_conta",
	                "icon",
	                "vs",
	            ]);
	    }
	}
