	class NineSkyFloorRewardView extends BaseView1 {
	    constructor() {
	        super();
	        this.base_file = "nineSky";
	        this.layout_file = "NineSkyFloorRewardView";
	        this.layer_value = Enum_UILayer.Activity;
	        this.use_background = true;
	        this.background_alpha = 0;
	        this.click_bg_toClose = true;
	        this.destroy_imm = true;
	        this.is_center = true;
	        this.nine_sky_model = NineSkyModel.GetInstance();
	        this.goods_model = GoodsModel.GetInstance();
	        this.item_list = null;
	        this.floor = null;
	        this.left_time = 5;
	        this.count_down_id = null;
	        this.end_time = null;
	        this.preload_server_config = {
	            "config_nine": false,
	        };
	        this.load_callback = () => {
	            this.LoadSuccess();
	        };
	        this.open_callback = () => {
	            this.UpdateView();
	        };
	        this.close_callback = () => {
	            this.Remove();
	        };
	    }
	    LoadSuccess() {
	        this._panel_reward.hScrollBarSkin = "";
	        Util.AddClickEvent(this._img_close, () => {
	            this.Close();
	        }, this, true, null, null, null, null, LuaSoundManager.SOUND_UI.CLOSE);
	    }
	    UpdateView() {
	        if (!this.floor) {
	            return;
	        }
	        this.voice = CommonManager.GetInstance().PlayFightingVoice(2);
	        let nine_cfg = ResManager.GetInstance().GetGameConfigFromCache(this, "config_nine", false);
	        let cfg = nine_cfg[this.nine_sky_model.server_type + "@" + this.floor];
	        let list = JSON.parse(cfg.award);
	        let len = list.length;
	        if (!this.item_list) {
	            this.item_list = [];
	        }
	        let i = len;
	        if (i < this.item_list.length) {
	            do {
	                this.item_list[i].SetVisible(false);
	                i = i + 1;
	            } while ((i < this.item_list.length));
	        }
	        if (len > 0) {
	            let item;
	            for (let key in list) {
	                item = this.item_list[key];
	                if (!item) {
	                    item = new BaseAwardItem(this._panel_reward);
	                    item.SetItemSize(85, 85);
	                    this.item_list[key] = item;
	                    item.Load();
	                }
	                item.SetPosition(Number(key) * 90, 0);
	                let vo = list[key];
	                let [type_id, lock] = this.goods_model.GetMappingTypeId(vo[0], vo[1]);
	                let goods_vo = this.goods_model.GetGoodsBasicByTypeId(type_id);
	                if (goods_vo) {
	                    item.SetData(goods_vo.type_id, vo[2], lock);
	                }
	                else {
	                    console.log("goods_vo is null TypeID:" + vo.typeId);
	                }
	                item.SetVisible(true);
	            }
	        }
	        if (len <= 5) {
	            this._panel_reward.width = len * 90;
	        }
	        else {
	            this._panel_reward.width = 460;
	        }
	        this._lb_desc.text = "恭贺您首次成功晋升至九魂妖塔" + this.floor + "层";
	        this.StartTime();
	    }
	    StartTime() {
	        this.CancelTime();
	        this.end_time = this.left_time + TimeUtil.getServerTime();
	        let loop_func = () => {
	            let left_time = this.end_time - TimeUtil.getServerTime();
	            if (left_time < 0) {
	                this.Close();
	                return;
	            }
	            this._lb_count_time.text = left_time + "秒后自动关闭";
	        };
	        this.count_down_id = GlobalTimerQuest.AddPeriodQuest(loop_func, 1, -1);
	        loop_func();
	    }
	    CancelTime() {
	        if (this.count_down_id) {
	            GlobalTimerQuest.CancelQuest(this.count_down_id);
	            this.count_down_id = null;
	        }
	    }
	    Remove() {
	        if (this.voice) {
	            SoundManager.GetInstance().StopSoundEffect(this.voice);
	            this.voice = null;
	        }
	        this.CancelTime();
	        if (this.item_list) {
	            for (let _tmpi in this.item_list) {
	                var obj = this.item_list[_tmpi];
	                obj.DeleteMe();
	            }
	            this.item_list = false;
	        }
	    }
	    Open(...new_args) {
	        let parm = new_args;
	        if (parm) {
	            this.floor = parm[0];
	        }
	        super.Open();
	    }
	    GetComponents() {
	        [
	            this._img_bg,
	            this._img_close,
	            this._img_bg2,
	            this._lb_desc,
	            this._lb_count_time,
	            this._panel_reward,
	            this._img_bg3,
	            this._lb_title,
	        ]
	            = this.GetChildrenByNames([
	                "_img_bg",
	                "_img_close",
	                "_img_bg2",
	                "_lb_desc",
	                "_lb_count_time",
	                "_panel_reward",
	                "_img_bg3",
	                "_lb_title",
	            ]);
	    }
	}
	window["NineSkyFloorRewardView"] = NineSkyFloorRewardView;
	NineSkyFloorRewardView["class_name"] = "NineSkyFloorRewardView";

	class NineSkyReliveView extends BaseView1 {
	    constructor() {
	        super();
	        this.base_file = "nineSky";
	        this.layout_file = "NineSkyReliveView";
	        this.layer_value = Enum_UILayer.Activity;
	        this.destroy_imm = true;
	        this.change_scene_close = true;
	        this.use_background = true;
	        this.background_alpha = 0;
	        this.not_close_by_android_back_key = true;
	        this.is_center = true;
	        this.nine_sky_model = NineSkyModel.GetInstance();
	        this.role_mgr = RoleManager.GetInstance();
	        this.goods_model = GoodsModel.GetInstance();
	        this.scene_mgr = SceneManager.GetInstance();
	        this.left_time_id = null;
	        this.left_time = 10;
	        this.relive_cost = null;
	        this.end_time = null;
	        let voice;
	        this.preload_server_config = {
	            "config_nine_key_value": false,
	            "config_nine": false,
	        };
	        this.load_callback = () => {
	            voice = CommonManager.GetInstance().PlayFightingVoice(1);
	            this.LoadSuccess();
	        };
	        this.open_callback = () => {
	            this.UpdateView();
	        };
	        this.close_callback = () => {
	            if (voice) {
	                SoundManager.GetInstance().StopSoundEffect(voice);
	                voice = null;
	            }
	            this.Remove();
	        };
	    }
	    LoadSuccess() {
	        this._html_kill_msg.style.color = "#663915";
	        this._html_kill_msg.style.fontSize = 20;
	        this._html_kill_msg.style.wordWrap = false;
	        this._html_kill_msg.style.bold = true;
	        let relive_func = () => {
	            GlobalEventSystem.Fire(EventName.RELIVE_BY_TYPE, 17);
	        };
	        Util.AddClickEvent(this._box_now_relive, () => {
	            if (this.relive_cost) {
	                let style = this.relive_cost[0];
	                let cost_count = this.relive_cost[2];
	                let jin_lock = this.role_mgr.GetMainRoleVo().jinLock;
	                let jin = this.role_mgr.GetMainRoleVo().jin;
	                if (jin_lock < Number(cost_count) && jin + jin_lock >= Number(cost_count)) {
	                    let str = "<font color='#ff4f50'>当前绑玉数量不足，是否消耗勾玉代替？</font>";
	                    let content = str;
	                    Alert.Show(content, Alert_Type.Two, relive_func, null, "确定", "取消");
	                }
	                else {
	                    relive_func();
	                }
	            }
	        }, this, true);
	        Util.AddClickEvent(this._box_safe_relive, () => {
	            GlobalEventSystem.Fire(EventName.RELIVE_BY_TYPE, 16);
	        }, this, true);
	        Util.AddClickEvent(this._img_streng, () => {
	            DailyModel.GetInstance().Fire(DailyEvent.OPEN_VIEW, "DailyView", 3, 0);
	        }, this, true);
	    }
	    UpdateView() {
	        let nine_key_value_cfg = ResManager.GetInstance().GetGameConfigFromCache(this, "config_nine_key_value", false);
	        let relive_cost = nine_key_value_cfg[9].value;
	        let vo = JSON.parse(relive_cost);
	        vo = vo && vo[0];
	        if (vo) {
	            this._lb_relive_cost.text = "x" + vo[2];
	            this.relive_cost = vo;
	            let [type_id, lock] = this.goods_model.GetMappingTypeId(vo[0], vo[1]);
	            let goods_vo = this.goods_model.GetGoodsBasicByTypeId(type_id);
	            if (goods_vo) {
	                ResManager.GetInstance().SetOutsideImageSprite(this, this._img_icon, GameResPath.GetGoodsIconPath(goods_vo.goods_icon));
	            }
	        }
	        this._html_kill_msg.innerHTML = `您已经被${HtmlColorTxt(this.scene_mgr.killerName, "'#e25a00'")}杀死`;
	        this._html_kill_msg.callLater(() => {
	            this._html_kill_msg.x = (this.display_obj.width - this._html_kill_msg.width) / 2;
	        });
	        if (this.scene_mgr.killerType == SceneBaseType.Role) {
	            this._lb_fighting_difference.visible = this._lb_desc.visible = true;
	            let role_vo = this.scene_mgr.GetRoleVo(this.scene_mgr.killerId);
	            let role_fight = 0;
	            if (role_vo) {
	                role_fight = role_vo.fighting;
	            }
	            let fight_off = this.role_mgr.GetMainRoleVo().fighting - role_fight;
	            this._lb_fighting_difference.text = String(Math.abs(fight_off));
	            this._lb_fighting_difference.color = fight_off >= 0 && "#009916" || "#fe1a1a";
	            if (fight_off >= 0) {
	                this._img_down.visible = false;
	                this._img_up.visible = true;
	            }
	            else {
	                this._img_up.visible = false;
	                this._img_down.visible = true;
	            }
	        }
	        else {
	            this._lb_fighting_difference.visible = this._lb_desc.visible = this._img_up.visible = this._img_down.visible = false;
	        }
	        if (this.scene_mgr.killerType == SceneBaseType.Monster) {
	            this._lb_fighting_difference.text = "0";
	            this._lb_fighting_difference.color = ColorUtil.TryParseHtmlString("#599F2C");
	            this._img_down.visible = false;
	            this._img_up.visible = false;
	        }
	        let id = this.scene_mgr.GetSceneId();
	        let floor = id - 27010;
	        if (floor < 0) {
	            floor = id - 27000;
	        }
	        this.StartTime();
	    }
	    StartTime() {
	        this.CancelTime();
	        this.end_time = this.left_time + TimeUtil.getServerTime();
	        let loop_func = () => {
	            let left_time = this.end_time - TimeUtil.getServerTime();
	            if (left_time < 0) {
	                this.CancelTime();
	                GlobalEventSystem.Fire(EventName.RELIVE_BY_TYPE, 16);
	                return;
	            }
	            this._lb_safe_relive.text = "安全复活(" + left_time + ")";
	        };
	        this.left_time_id = GlobalTimerQuest.AddPeriodQuest(loop_func, 1, -1);
	        loop_func();
	    }
	    CancelTime() {
	        if (this.left_time_id) {
	            GlobalTimerQuest.CancelQuest(this.left_time_id);
	            this.left_time_id = null;
	        }
	    }
	    Remove() {
	        this.CancelTime();
	    }
	    GetComponents() {
	        [
	            this._img_bg,
	            this._img_bg2,
	            this._img_bg3,
	            this._img_bg4,
	            this._img_streng,
	            this._box_safe_relive,
	            this._img_safe_relive,
	            this._lb_safe_relive,
	            this._box_now_relive,
	            this._img_now_relive,
	            this._lb_now_relive,
	            this._html_kill_msg,
	            this._lb_desc,
	            this._img_up,
	            this._img_down,
	            this._lb_fighting_difference,
	            this._img_icon,
	            this._lb_relive_cost,
	        ]
	            = this.GetChildrenByNames([
	                "_img_bg",
	                "_img_bg2",
	                "_img_bg3",
	                "_img_bg4",
	                "_img_streng",
	                "_box_safe_relive",
	                "_img_safe_relive",
	                "_lb_safe_relive",
	                "_box_now_relive",
	                "_img_now_relive",
	                "_lb_now_relive",
	                "_html_kill_msg",
	                "_lb_desc",
	                "_img_up",
	                "_img_down",
	                "_lb_fighting_difference",
	                "_img_icon",
	                "_lb_relive_cost",
	            ]);
	    }
	}
